package com.examservice.presentation.advice;import com.examservice.domain.exception.*;import com.examservice.presentation.response.ApiResponse;import org.springframework.http.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(NotFoundException.class)@ResponseStatus(HttpStatus.NOT_FOUND)ApiResponse<Void>notFound(Exception e){return err("RESOURCE_NOT_FOUND",e.getMessage());}@ExceptionHandler({ForbiddenException.class,AccessDeniedException.class})@ResponseStatus(HttpStatus.FORBIDDEN)ApiResponse<Void>forbidden(Exception e){return err("FORBIDDEN",e.getMessage());}@ExceptionHandler(InsufficientQuestionsException.class)@ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)ApiResponse<Void>insufficient(Exception e){return err("INSUFFICIENT_APPROVED_QUESTIONS",e.getMessage());}@ExceptionHandler({InvalidMatrixException.class,IllegalArgumentException.class,MethodArgumentNotValidException.class})@ResponseStatus(HttpStatus.BAD_REQUEST)ApiResponse<Void>bad(Exception e){return err("INVALID_EXAM_MATRIX",e instanceof MethodArgumentNotValidException?"Request validation failed":e.getMessage());}@ExceptionHandler(Exception.class)@ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)ApiResponse<Void>unknown(Exception e){return err("INTERNAL_ERROR","Unexpected server error");}private ApiResponse<Void>err(String c,String m){return new ApiResponse<>(false,c,m,null);}}
